import { BackdropLayer, Icon, ScreenPage, Text } from '@drizztdourden08/tessera';
import type { Backdrop } from '@drizztdourden08/tessera';

const night: Backdrop = { kind: 'image', src: '/art/night.png', position: 'center bottom', pixelated: true };

const SavesPage = () => (
  <ScreenPage icon={<Icon name="save" />} title="Saves" backdrop={<BackdropLayer backdrop={night} />}>
    <Text>Three saves</Text>
  </ScreenPage>
);

import { Box, Text } from '@drizztdourden08/tessera';

const SpritePanel = () => (
  <Box as="aside" surface="raised" aria-label="Sprites" className="sprite-panel">
    <Text variant="overline">Sprites</Text>
    <Box surface="sunken" className="sprite-panel__list">
      <Text>Link</Text>
      <Text>Zelda</Text>
    </Box>
  </Box>
);

import { Button, Callout, Icon } from '@drizztdourden08/tessera';

const PackageBanner = ({ onGet }: { onGet: () => void }) => (
  <Callout
    tone="danger"
    title="The package could not be installed"
    icon={<Icon name="triangle-alert" size={16} />}
    action={<Button size="sm" variant="danger" onClick={onGet}>Get the package</Button>}
  >
    Check your connection and try again.
  </Callout>
);

import { Center, Text } from '@drizztdourden08/tessera';

const LobbyWaiting = () => (
  <Center direction="column" gap="sm" className="lobby-empty">
    <Text variant="title">Lobby</Text>
    <Text variant="subtitle">Waiting for the host to start the session</Text>
  </Center>
);

import { Card, DensityScope, Field, Select, Slider } from '@drizztdourden08/tessera';
import { useState } from 'react';

const ANCHORS = [{ value: 'top-left', label: 'Top left' }, { value: 'top-right', label: 'Top right' }];

const Inspector = () => {
  const [anchor, setAnchor] = useState('top-left');
  const [width, setWidth] = useState(160);
  return (
    <DensityScope density="compact">
      <Card title="Health bar">
        <Field label="Anchor">
          <Select options={ANCHORS} value={anchor} onChange={setAnchor} />
        </Field>
        <Field label="Width">
          <Slider value={width} max={400} onChange={setWidth} />
        </Field>
      </Card>
    </DensityScope>
  );
};

import { Disclosure, Paragraph } from '@drizztdourden08/tessera';

const ReleaseNotes = ({ notes }: { notes: string }) => (
  <Disclosure summary="What is new">
    <Paragraph tone="dim">{notes}</Paragraph>
  </Disclosure>
);

import { Card, Grid, ProgressBar } from '@drizztdourden08/tessera';
import type { ReactNode } from 'react';

const RunDashboard = ({ activity, players }: { activity: ReactNode; players: ReactNode }) => (
  <Grid minColWidth={288} gap="lg" dense aria-label="Randomizer run">
    <Card title="Summary" subtitle="Seed 48213, online">Profile Hyrule run, 3 players.</Card>
    <Card title="Progress"><ProgressBar value={42} max={216} label="Checks taken" /></Card>
    <Card title="Recent activity">{activity}</Card>
    <Grid.Cell span={2}><Card title="Players">{players}</Card></Grid.Cell>
    <Card title="Item pool">216 locations</Card>
  </Grid>
);

import { Icon, Inline, Status, Text } from '@drizztdourden08/tessera';

const SessionRow = () => (
  <Inline>
    <Icon name="gamepad-2" />
    <Text>Session 4</Text>
    <Status tone="success" dot>Connected</Status>
  </Inline>
);

import { List, ListItem } from '@drizztdourden08/tessera';

const Steps = () => (
  <List ordered start={1}>
    <ListItem>Download the zip.</ListItem>
    <ListItem>
      Unpack it anywhere.
      <List>
        <ListItem>Keep the folder name short.</ListItem>
      </List>
    </ListItem>
  </List>
);

import { PageFrame, Title } from '@drizztdourden08/tessera';

const AccountPage = () => (
  <PageFrame width="md">
    <Title>Account</Title>
  </PageFrame>
);

import { Hero, PageRoot, SiteHeader } from '@drizztdourden08/tessera';
import type { SiteHeaderProps } from '@drizztdourden08/tessera';

interface HomePageProps {
  header: SiteHeaderProps;
}

const HomePage = ({ header }: HomePageProps) => (
  <PageRoot>
    <SiteHeader {...header} />
    <Hero size="full" title="Relic of the Past" art={{ kind: 'image', src: '/art/hills.png', motion: 'pan' }} />
  </PageRoot>
);

import type { ReactNode } from 'react';
import { Grid, ScrollArea } from '@drizztdourden08/tessera';

const Library = ({ cards }: { cards: ReactNode[] }) => (
  <ScrollArea scrollbar="slim" className="library">
    <Grid minColWidth={224} gap="sm">
      {cards}
    </Grid>
  </ScrollArea>
);

import { useState } from 'react';
import { SegmentedControl } from '@drizztdourden08/tessera';

const ScalePicker = () => {
  const [scale, setScale] = useState('2x');
  return (
    <SegmentedControl
      label="Window scale"
      value={scale}
      onChange={setScale}
      options={[
        { value: '1x', label: '1x' },
        { value: '2x', label: '2x' },
        { value: 'fit', label: 'Fit window' },
      ]}
    />
  );
};

import { Select } from '@drizztdourden08/tessera';

interface TintPickerProps {
  tint: string;
  onTint: (tint: string) => void;
}

const TintPicker = ({ tint, onTint }: TintPickerProps) => (
  <Select
    value={tint}
    onChange={onTint}
    options={[{ value: 'none', label: 'No tint' }]}
    groups={[
      { label: 'Warm', options: [{ value: 'red', label: 'Red' }, { value: 'amber', label: 'Amber' }] },
      { label: 'Cool', options: [{ value: 'blue', label: 'Blue' }, { value: 'teal', label: 'Teal' }] },
    ]}
  />
);

import { Sparkline } from '@drizztdourden08/tessera';

const FrameRateTrend = ({ samples }: { samples: readonly number[] }) => (
  <Sparkline values={samples} length={40} min={0} max={165} band={{ from: 0, to: 60, tone: 'danger' }} tone="success" dot label="Frame rate" />
);

import { SpeechBubble } from '@drizztdourden08/tessera';

const SearchTip = () => (
  <SpeechBubble tone="info" pointer="left" pointerOffset={24} role="status">
    Type to search screens, settings and actions. Press Enter to open the first result.
  </SpeechBubble>
);

import { StackedBar } from '@drizztdourden08/tessera';

const gigabytes = (value: number) => `${value.toFixed(1)} GB`;

const MemoryBar = () => (
  <StackedBar
    segments={[{ id: 'game', label: 'Game', value: 4.2 }, { id: 'browser', label: 'Browser', value: 1.8 }]}
    total={16}
    legend
    label="Memory"
    format={gigabytes}
  />
);

import { defineStatuses, Status } from '@drizztdourden08/tessera';

const ENGINE_STATES = defineStatuses({
  ready: { label: 'Ready', tone: 'success' },
  building: { label: 'Setting up', tone: 'warning', pulse: true },
  failed: { label: 'Broken', tone: 'danger' },
  unknown: { label: 'Checking', tone: 'neutral' },
});

const Sync = () => <Status tone="warning" dot pulse>Syncing</Status>;

const EngineState = ({ state }: { state?: 'ready' | 'building' | 'failed' }) => (
  <Status map={ENGINE_STATES} value={state} fallback="unknown" dot />
);

import { Text } from '@drizztdourden08/tessera';

const SyncLine = () => (
  <Text.P>
    <Text variant="caption" tone="muted">Last synced 12 seconds ago</Text>
    <Text variant="caption" tone="faint"> · Hold Shift to snap</Text>
  </Text.P>
);

import { Button, ToolFrame, ToolGroups } from '@drizztdourden08/tessera';
import type { ReactNode } from 'react';

const ScriptEditor = ({ script, onRun }: { script: ReactNode; onRun: () => void }) => (
  <ToolFrame
    as="section"
    aria-label="Intro script"
    padded
    toolbar={<ToolGroups groups={[{ id: 'file', label: 'File', content: <Button size="sm" onClick={onRun}>Run</Button> }]} />}
  >
    {script}
  </ToolFrame>
);

import { Button, ToolGroups } from '@drizztdourden08/tessera';

const FileActions = ({ onSave, onExport }: { onSave: () => void; onExport: () => void }) => (
  <ToolGroups
    groups={[
      { id: 'save', label: 'Save to this app', content: <Button size="sm" onClick={onSave}>Save</Button> },
      { id: 'export', label: 'Export a file', content: <Button size="sm" variant="secondary" onClick={onExport}>Export PNG</Button> },
    ]}
  />
);

import { ActionBar } from '@drizztdourden08/tessera';
import type { ActionItem } from '@drizztdourden08/tessera';

interface PresetHeaderProps {
  name: string;
  onDuplicate: () => void;
  onDelete: () => void;
  onSave: () => void;
}

const PresetHeader = ({ name, onDuplicate, onDelete, onSave }: PresetHeaderProps) => {
  const actions: ActionItem[] = [
    { id: 'duplicate', label: 'Duplicate', icon: 'copy', onSelect: onDuplicate },
    { id: 'delete', label: 'Delete', icon: 'trash-2', kind: 'danger', onSelect: onDelete, confirm: { title: `Delete ${name}?`, confirmLabel: `Delete ${name}` } },
    { id: 'save', label: 'Save', icon: 'save', kind: 'primary', onSelect: onSave },
  ];
  return <ActionBar label={name} actions={actions} />;
};

import { ActionTile } from '@drizztdourden08/tessera';

const SessionTiles = ({ address, onShowPlayers, onStop }: { address: string; onShowPlayers: () => void; onStop: () => void }) => (
  <>
    <ActionTile label="Players" icon="users" value="2 / 3" unit="connected" onOpen={onShowPlayers} openLabel="Show the Players widget" />
    <ActionTile label="Address" icon="link" value={address} action={{ label: 'Copy address', copy: address }} />
    <ActionTile
      label="Uptime"
      icon="clock"
      value="42 min"
      status={{ label: 'hosting', tone: 'success' }}
      action={{ label: 'Stop', icon: 'square', tone: 'danger', onSelect: onStop }}
    />
  </>
);

import { useState } from 'react';
import { AnchorPicker } from '@drizztdourden08/tessera';
import type { Anchor } from '@drizztdourden08/tessera';

const CanvasAnchor = () => {
  const [anchor, setAnchor] = useState<Anchor>('center');
  return <AnchorPicker label="Anchor" variant="arrows" value={anchor} onChange={setAnchor} />;
};

import { ArmedIconButton } from '@drizztdourden08/tessera';

const SaveSlotTools = ({ slot, onLoad, onSave, onDelete }: { slot: string; onLoad: () => void; onSave: () => void; onDelete: () => void }) => (
  <>
    <ArmedIconButton icon="load-state" tone="info" label={`Load ${slot}`} onConfirm={onLoad} />
    <ArmedIconButton icon="save-state" tone="warning" label={`Overwrite ${slot}`} onConfirm={onSave} />
    <ArmedIconButton icon="trash-2" tone="danger" label={`Delete ${slot}`} onConfirm={onDelete} />
  </>
);

import { Carousel, Hero } from '@drizztdourden08/tessera';

interface Featured {
  id: string;
  name: string;
  banner: string;
}

const FeaturedPacks = ({ items }: { items: readonly Featured[] }) => (
  <Carousel
    label="Featured"
    turnEvery={8000}
    slides={items.map((item) => ({
      id: item.id,
      label: item.name,
      content: <Hero eyebrow="Featured" title={item.name} backdrop={{ kind: 'image', src: item.banner }} />,
    }))}
  />
);

import { CheckList } from '@drizztdourden08/tessera';
import type { Check } from '@drizztdourden08/tessera';

interface ServerTestProps {
  server: string;
  checks: Check[];
}

const ServerTest = ({ server, checks }: ServerTestProps) => {
  const ready = checks.every((check) => check.state === 'pass' || check.state === 'warn');
  return <CheckList summary={ready ? `${server} is ready` : `${server} is not ready`} checks={checks} />;
};

import { CollapseToggle } from '@drizztdourden08/tessera';
import { useId, useState } from 'react';
import type { ReactNode } from 'react';

const ProfileRail = ({ children }: { children: ReactNode }) => {
  const [collapsed, setCollapsed] = useState(false);
  const id = useId();
  return (
    <div className="profile-rail" id={id}>
      <CollapseToggle collapsed={collapsed} onToggle={() => setCollapsed(!collapsed)} label="profiles" controls={id} className="profile-rail__toggle" />
      {!collapsed && children}
    </div>
  );
};

import { ColorPicker } from '@drizztdourden08/tessera/color-picker';

interface BrushColorProps {
  color: string;
  onColor: (hex: string) => void;
}

const BrushColor = ({ color, onColor }: BrushColorProps) => (
  <ColorPicker value={color} onChange={onColor} disableAlpha />
);

import { CommandInput } from '@drizztdourden08/tessera';

const ServerConsole = ({ send }: { send: (command: string) => void }) => (
  <CommandInput placeholder="/players" storageKey="console.history" commands={['/players', '/hint', '/save']} onSubmit={send} />
);

import { ContentHeader, HeaderAnchorNav, Icon } from '@drizztdourden08/tessera';

const GeneralHeader = ({ section, onSection }: { section: string; onSection: (id: string) => void }) => (
  <ContentHeader
    icon={<Icon name="settings" />}
    title="General"
    strip={<HeaderAnchorNav items={[{ id: 'startup', label: 'Startup' }, { id: 'tray', label: 'Tray' }]} activeId={section} onSelect={onSection} ariaLabel="General sections" />}
  />
);

import { ContextMenu } from '@drizztdourden08/tessera';
import type { MenuGroup } from '@drizztdourden08/tessera';

interface TabProps {
  name: string;
  onRename: () => void;
  onClose: () => void;
}

const Tab = ({ name, onRename, onClose }: TabProps) => {
  const groups: MenuGroup[] = [{
    id: 'tab',
    items: [
      { id: 'rename', icon: 'pencil', label: 'Rename', onSelect: onRename },
      { separator: true },
      { id: 'close', icon: 'x', label: 'Close tab', tone: 'danger', onSelect: onClose },
    ],
  }];
  return <ContextMenu groups={groups} label={name}>{name}</ContextMenu>;
};

import { ControllerSilhouette, SvgCircle, SvgText } from '@drizztdourden08/tessera';

const face = { x: 278, y: 76, r: 32 };

const JumpHint = () => {
  return (
    <ControllerSilhouette variant="offset" label="Jump is the bottom face button">
      <SvgCircle cx={face.x} cy={face.y + face.r / 2} r={face.r / 3} />
      <SvgText x={face.x} y={face.y + face.r + 14} textAnchor="middle">Jump</SvgText>
    </ControllerSilhouette>
  );
};

import { CopyButton } from '@drizztdourden08/tessera';

const AboutActions = ({ debugInfo }: { debugInfo: () => string }) => (
  <CopyButton text={debugInfo} label="Copy debug info" showLabel variant="secondary" />
);

import { CopyValue } from '@drizztdourden08/tessera';

const RoomAddress = ({ address }: { address: string }) => (
  <CopyValue value={address} label="room address" mono truncate="middle" />
);

import { DataTable } from '@drizztdourden08/tessera';
import type { FieldDescriptor } from '@drizztdourden08/tessera';

interface Peer {
  id: string;
  name: string;
  state: string;
}

const openGroups = ['Connected'];

interface PeerTableProps {
  peers: Peer[];
  schema: FieldDescriptor[];
}

const PeerTable = ({ peers, schema }: PeerTableProps) => (
  <DataTable
    rows={peers}
    schema={schema}
    getRowId={(peer) => peer.id}
    fallbackGroupBy={['state']}
    defaultExpanded={openGroups}
    countLabel={['peer', 'peers']}
  />
);

import { Dialog } from '@drizztdourden08/tessera';

const ReadmeDialog = ({ open, close }: { open: boolean; close: () => void }) => (
  <Dialog open={open} title="README" message="" size="lg" confirmLabel="Close" hideCancel onConfirm={close} onCancel={close}>
    Release notes go here.
  </Dialog>
);

import { Button, DialogShell } from '@drizztdourden08/tessera';

const DetailsDialog = ({ open, close }: { open: boolean; close: () => void }) => (
  <DialogShell open={open} onClose={close} title="Friday async" size="md" actions={<Button onClick={close}>Close</Button>}>
    Eight players are connected.
  </DialogShell>
);

import { DocumentTabs } from '@drizztdourden08/tessera';
import type { DocumentTab } from '@drizztdourden08/tessera';

interface OpenDrawingsProps {
  drawings: DocumentTab[];
  activeId: string;
  open: (id: string) => void;
  askToClose: (id: string) => void;
  move: (from: number, to: number) => void;
}

const OpenDrawings = ({ drawings, activeId, open, askToClose, move }: OpenDrawingsProps) => (
  <DocumentTabs
    label="Open drawings"
    tabs={drawings}
    activeId={activeId}
    onActivate={open}
    onClose={askToClose}
    onMove={move}
    overflowMenu
  />
);

import { DropdownMenu } from '@drizztdourden08/tessera';
import type { MenuGroup } from '@drizztdourden08/tessera';

interface LayoutMenuProps {
  locked: boolean;
  onLock: () => void;
  onSave: () => void;
  onReset: () => void;
}

const LayoutMenu = ({ locked, onLock, onSave, onReset }: LayoutMenuProps) => {
  const groups: MenuGroup[] = [{
    id: 'layout',
    label: 'Layout',
    items: [
      { id: 'lock', icon: 'lock', label: 'Lock widgets', checked: locked, onSelect: onLock },
      { id: 'save', icon: 'save', label: 'Save layout', onSelect: onSave },
      { separator: true },
      { id: 'reset', icon: 'rotate-ccw', label: 'Reset layout', kind: 'confirm', onSelect: onReset },
    ],
  }];
  return <DropdownMenu trigger={{ label: 'Layout', icon: 'layout-grid' }} groups={groups} />;
};

import { useState } from 'react';
import { DynamicInput, Field } from '@drizztdourden08/tessera';
import type { PatternValue } from '@drizztdourden08/tessera';

const SLOTS = {
  code: { chars: 'ABCDEFGHJKLMNOPQRSTVWXYZ0123456789', aliases: { I: '1', L: '1', O: '0' } },
};

const LobbyCode = () => {
  const [value, setValue] = useState<PatternValue>({ code: null });
  return (
    <Field label="Lobby code">
      <DynamicInput pattern="{code:text len6 upper}" value={value} onChange={setValue} slots={SLOTS} />
    </Field>
  );
};

import { FileList } from '@drizztdourden08/tessera';
import type { FileEntry } from '@drizztdourden08/tessera';

interface RunOutputProps {
  files: FileEntry[];
  openPath: (path: string) => void;
  showInFolder: (path: string) => void;
}

const RunOutput = ({ files, openPath, showInFolder }: RunOutputProps) => (
  <FileList
    label="Output"
    files={files}
    onOpen={openPath}
    onReveal={showInFolder}
    empty="No output files yet. They show here once the seed is generated."
  />
);

import { FloatingPrompt } from '@drizztdourden08/tessera';
import type { ReactNode } from 'react';

interface CanvasAreaProps {
  canvas: ReactNode;
  pending: number;
  apply: () => void;
  cancel: () => void;
}

const CanvasArea = ({ canvas, pending, apply, cancel }: CanvasAreaProps) => (
  <div style={{ position: 'relative' }}>
    {canvas}
    <FloatingPrompt
      open={pending > 0}
      message={`Apply the ${pending} pending edits to the canvas.`}
      actions={[
        { id: 'apply', label: 'Apply', onSelect: apply },
        { id: 'cancel', label: 'Cancel', onSelect: cancel, cancel: true },
      ]}
    />
  </div>
);

import { FormGroupTabs } from '@drizztdourden08/tessera';
import type { FormGroupTab } from '@drizztdourden08/tessera';

const OptionGroups = ({ groups, groupId, setGroupId, query, setQuery }: {
  groups: FormGroupTab[];
  groupId: string;
  setGroupId: (id: string) => void;
  query: string;
  setQuery: (query: string) => void;
}) => <FormGroupTabs tabs={groups} activeTab={groupId} onTabChange={setGroupId} query={query} onQueryChange={setQuery} />;

import { FormRow, Slider } from '@drizztdourden08/tessera';
import type { ScaleLabelEntry } from '@drizztdourden08/tessera';

const BALANCING: ScaleLabelEntry[] = [[0, 'Disabled'], [50, 'Normal'], [99, 'Extreme']];

const BalancingRow = ({ value, onChange }: { value: number; onChange: (value: number) => void }) => (
  <FormRow label="Progression Balancing" description="Moves progression earlier." changed={value !== 50} onReset={() => onChange(50)}>
    <Slider value={value} onChange={onChange} min={0} max={99} labels={BALANCING} input />
  </FormRow>
);

import { useMemo } from 'react';
import { BrandMark, Button, GuidedTour, useGuidedTour } from '@drizztdourden08/tessera';
import type { TourStep } from '@drizztdourden08/tessera';

const HomeTour = ({ openSettings }: { openSettings: () => void }) => {
  const steps = useMemo<TourStep[]>(() => [
    { id: 'welcome', intro: true, art: <BrandMark app="archipelia" size="xl" />, title: 'Welcome', body: 'A short walk through the screen.', mascot: 'wave' },
    { id: 'pages', target: { tour: 'pages' }, placement: 'right-start', title: 'Pages', body: 'Every page lives here.' },
    { id: 'gear', target: { tour: 'gear' }, advance: 'click', title: 'Settings', body: 'Click the gear to open the settings.' },
    { id: 'panel', target: { tour: 'settings' }, title: 'Settings', body: 'Changes apply at once.', onEnter: openSettings },
  ], [openSettings]);
  const tour = useGuidedTour({ steps });
  return (
    <>
      <Button onClick={() => tour.start()}>Take the tour</Button>
      <GuidedTour tour={tour} mascot="auto" keep={[{ tour: 'title-bar' }]} />
    </>
  );
};

import { FactsPanel, H2, InfoScreen, Logo } from '@drizztdourden08/tessera';

const AboutScreen = ({ onClose }: { onClose: () => void }) => (
  <InfoScreen
    title="About"
    onClose={onClose}
    lead={<><Logo brand="rotp" variant="app-icon" size="xl" title="" /><H2>Relic of the Past</H2></>}
    footer="Names and marks belong to their owners."
  >
    <FactsPanel label="This build" groups={[[{ label: 'Version', value: '0.9.2', mono: true }]]} />
  </InfoScreen>
);

import { useState } from 'react';
import { InlineEdit } from '@drizztdourden08/tessera';

const CardTitle = () => {
  const [title, setTitle] = useState('Fix the login redirect');
  return (
    <InlineEdit
      label="Title"
      value={title}
      onCommit={setTitle}
      placeholder="Add a title"
      validate={(text) => (text.length < 3 ? 'Use at least 3 characters.' : undefined)}
    />
  );
};

import { ItemCard } from '@drizztdourden08/tessera';
import { Icon, Tag } from '@drizztdourden08/tessera';

interface GameCardProps {
  name: string;
  genre: string;
  version: string;
  onInstall: () => void;
  onOpen: () => void;
}

const GameCard = ({ name, genre, version, onInstall, onOpen }: GameCardProps) => (
  <ItemCard
    media={<Icon name="gamepad-2" size={40} />}
    eyebrow="Official"
    title={name}
    status={{ label: 'stable', tone: 'info' }}
    tags={[<Tag key="genre" variant="category" color="violet">{genre}</Tag>]}
    details={[`World ${version}`, 'For AP 0.6.7']}
    actions={[{ id: 'install', label: 'Install', icon: 'download', kind: 'primary', onSelect: onInstall }]}
    onOpen={onOpen}
  />
);

import { ItemList } from '@drizztdourden08/tessera';

interface Server {
  id: string;
  name: string;
  host: string;
}

const ServerList = ({ servers, selectedId, onSelect, onAdd, onRename, onDelete, loading, error }: {
  servers: Server[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAdd: () => void;
  onRename: (id: string, name: string) => void;
  onDelete: (id: string) => void;
  loading: boolean;
  error?: string;
}) => (
  <ItemList
    title="Servers"
    items={servers}
    getId={(server) => server.id}
    getName={(server) => server.name}
    render={(server) => ({ meta: server.host })}
    selectedId={selectedId}
    onSelect={onSelect}
    onCreate={onAdd}
